}

function requireTimestamp(value, fieldName) {
    const timestamp = requireString(value, fieldName);
    if (Number.isNaN(Date.parse(timestamp))) throw new Error(`Invalid schedule file: invalid ${fieldName}`);

    return timestamp;
}

